css:
.wrong-question-page {
  min-height: 100vh;
  background: #f8f9fc;
  font-family: "Noto Sans SC", "PingFang SC", sans-serif;
}
.wq-main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 32px 40px;
}
.wq-filter-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  background: #fff;
  padding: 16px 20px;
  border-radius: 14px;
  box-shadow: 0 1px 8px rgba(26, 43, 95, 0.04);
}
.filter-group {
  display: flex;
  align-items: center;
  gap: 8px;
}
.filter-group label {
  font-size: 13px;
  color: #5a6488;
  font-weight: 600;
}
.filter-group select {
  padding: 6px 12px;
  border: 1px solid #e8eaf0;
  border-radius: 8px;
  font-size: 13px;
  color: #1a2b5f;
  outline: none;
}
.filter-btn {
  padding: 8px 20px;
  background: linear-gradient(135deg, #1a2b5f, #1e3470);
  color: #fff;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 600;
}
.wq-body {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
}
.wq-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: #fff;
  border-radius: 14px;
  padding: 12px;
  box-shadow: 0 1px 8px rgba(26, 43, 95, 0.04);
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s;
  font-size: 14px;
  font-weight: 600;
  color: #5a6488;
  position: relative;
}
.nav-item:hover {
  background: #f8f9fc;
}
.nav-item.active {
  background: #1a2b5f;
  color: #fff;
}
.nav-badge {
  margin-left: auto;
  background: #c41e3a;
  color: #fff;
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 10px;
}
.wq-content {
  background: #fff;
  border-radius: 14px;
  padding: 24px;
  box-shadow: 0 1px 8px rgba(26, 43, 95, 0.04);
}
.section-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 20px;
}
.section-top h3 {
  font-size: 18px;
  font-weight: 800;
  color: #1a2b5f;
  margin: 0;
}
.section-tip {
  font-size: 12px;
  color: #8a8faa;
}
.empty-state {
  text-align: center;
  padding: 60px 0;
  color: #8a8faa;
}
.empty-icon {
  font-size: 48px;
}
.zhanti-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.zhanti-card {
  border: 1px solid #e8eaf0;
  border-radius: 12px;
  padding: 16px;
  transition: all 0.3s;
  cursor: pointer;
}
.zhanti-card.expiring {
  border-color: #fecaca;
  background: #fff5f5;
}
.card-top {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
}
.card-subject {
  font-size: 12px;
  font-weight: 700;
  color: #1a2b5f;
}
.card-days {
  font-size: 11px;
  color: #ef4444;
}
.card-title-text {
  font-size: 14px;
  color: #333;
  margin: 0 0 12px;
  line-height: 1.5;
}
.card-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: #8a8faa;
}
.card-bottom button {
  padding: 4px 12px;
  background: #1a2b5f;
  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 11px;
}
.expiring-notice {
  margin-top: 16px;
  padding: 12px;
  background: #fef3c7;
  border-radius: 10px;
  font-size: 13px;
  color: #92400e;
  text-align: center;
}
.review-options {
  display: flex;
  gap: 16px;
}
.review-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 24px;
  border-radius: 14px;
  border: 2px dashed #e8eaf0;
  cursor: pointer;
  transition: all 0.3s;
  flex: 1;
  font-size: 14px;
  font-weight: 600;
  color: #1a2b5f;
}
.review-option:hover {
  border-color: #c41e3a;
  background: #fef2f2;
}
.option-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.question-items {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.q-item {
  padding: 16px;
  border: 1px solid #e8eaf0;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s;
}
.q-item:hover {
  border-color: #cbd5e0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.q-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 6px;
}
.q-type {
  font-size: 11px;
  background: #eff6ff;
  color: #3b82f6;
  padding: 2px 8px;
  border-radius: 6px;
  font-weight: 600;
}
.q-date {
  font-size: 11px;
  color: #8a8faa;
}
.q-title {
  font-size: 14px;
  color: #1a2b5f;
  margin: 0 0 8px;
}
.q-tags {
  display: flex;
  gap: 6px;
}
.q-tags span {
  font-size: 10px;
  padding: 2px 8px;
  background: #f8f9fc;
  border-radius: 6px;
  color: #5a6488;
}

